function SMILe_Preprocessing(cfg)
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ SMILe Preprocessing Routine
%$$$$$$ JCM, current as of 03/23/2022
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ DO NOT EDIT THIS FILE
%$$$$$$ MAKE A COPY OF THIS FILE AND SAVE IT TO YOUR HARD DRIVE
%$$$$$$ THEN, AND ONLY THEN, MAKE IT WORK FOR YOUR UNIQUE SETTINGS
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ This routine is dependent on a number of EEGLAB toolboxes and a
%$$$$$$ couple of custom scripts. These are identified below. Make sure
%$$$$$$ that your EEGLAB installation has updated versions of all of these
%$$$$$$ toolboxes and custom scripts:
%$$$$$$
%$$$$$$ eeglab2019_1 (or newer)
%$$$$$$ - https://sccn.ucsd.edu/eeglab/download.php
%$$$$$$ loadcurry
%$$$$$$ - https://github.com/mattpontifex/loadcurry
%$$$$$$ neuroscanio1.3
%$$$$$$ - https://github.com/sccn/neuroscanio
%$$$$$$ icablinkmetrics
%$$$$$$ - https://github.com/mattpontifex/icablinkmetrics
%$$$$$$ cleanLine
%$$$$$$ - https://github.com/sccn/cleanline
%$$$$$$ clean_rawdata
%$$$$$$ - https://github.com/sccn/clean_rawdata
%$$$$$$ AMICA - this can be difficult to properly install - talk to me if
%$$$$$$     you have issues
%$$$$$$ - https://sccn.ucsd.edu/~jason/amica_web.html
%$$$$$$ Preconditioned ICA for Real Data (picard)
%$$$$$$ - https://github.com/pierreablin/picard
%$$$$$$ MARA
%$$$$$$ - https://irenne.github.io/artifacts/
%$$$$$$ ICLabel
%$$$$$$ - https://github.com/sccn/ICLabel
%$$$$$$ SASICA
%$$$$$$ - https://github.com/dnacombo/SASICA
%$$$$$$ fitTwoDipoles
%$$$$$$ - eeglab GUI download
%$$$$$$ Current Source Density (CSD) Interpolation using Spherical Splines 
%$$$$$$ - https://psychophysiology.cpmc.columbia.edu/Software/CSDtoolbox/
%$$$$$$ REST Infinity Reference
%$$$$$ - http://sccn.ucsd.edu/eeglab/plugins/REST1.2.zip
%$$$$$$
%$$$$$$ These are all available on the large storage computer (Z drive, 
%$$$$$$ normally) or through the EEGLAB GUI or an internet download
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Start file
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
tstart = tic;
fprintf('##################################################################################################################\n\n');
fprintf('Beginning PreProcessing Routine ----- '); disp(datestr(now))
fprintf('\n')
fprintf('##################################################################################################################\n\n');


%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ If EEGLAB has not been initialized, do this to load all toolboxes
%$$$$$$ in the MATLAB search path
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
try
    EEGLABcheck = evalin('base', 'ALLEEG');
    
catch

    if ~exist('EEGLABcheck','var')

%--------------------------------------------------------------------------
% Try to invoke EEGLAB, assuming EEGLAB is already on the path:
%--------------------------------------------------------------------------

    try
        [ALLEEG, EEG, CURRENTSET, ALLCOM] =  eeglab;

%--------------------------------------------------------------------------
% Catch error and request user to point to the parent EEGLAB folder:
%--------------------------------------------------------------------------
    catch
        dirname = uigetdir(matlabroot,'Navigate to the parent EEGLAB directory on this computer:');

%--------------------------------------------------------------------------
% Now add the EEGLAB folder to the search path and invoke EEGLAB:
%--------------------------------------------------------------------------
        addpath(dirname);
        [ALLEEG, EEG, CURRENTSET, ALLCOM] =  eeglab;
   
    end

%--------------------------------------------------------------------------
% End for conditional on EEGLAB:
%--------------------------------------------------------------------------
    end

%--------------------------------------------------------------------------
% End for conditional on EEGLABcheck:
%--------------------------------------------------------------------------
end


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Point to the EEGLAB installation directory
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
[eeglabdir, ~, ~] = fileparts(which('eeglab'));


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Generate a list of files over which to operate:
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%--------------------------------------------------------------------------
% Old usage that was dependent on my function "findfiles":
%--------------------------------------------------------------------------
% addpath('path/to/Utilities');
% f_names = findfiles('.cnt','path/to/data');

%--------------------------------------------------------------------------
% Newer implementation below now that MATLAB allows wildcard expansion:
%
% This requires a study-specific change to the data folder and also to the
% identifier to look for.
%--------------------------------------------------------------------------
if isfield(cfg, 'dataFolder') && ~isempty(cfg.dataFolder)
    dataFolder = cfg.dataFolder;
    
else
    dataFolder = uigetdir;
    
end

%--------------------------------------------------------------------------
% Which data folder on Windows:
%--------------------------------------------------------------------------
% if ispc
%     dataFolder = 'path/to/data';
% 
% %--------------------------------------------------------------------------
% % Which data folder on Mac:
% %--------------------------------------------------------------------------
% elseif ismac
%     dataFolder = '/Path/To/Your/Data';
%    
% %--------------------------------------------------------------------------
% % Which data folder on Linux:
% %--------------------------------------------------------------------------
% elseif isunix
%     dataFolder = '/Path/To/Your/Data';
%    
% end

%--------------------------------------------------------------------------
% Search term (identifier) to get specific files. Wildcards (the * in the
% code below) are accepted in newer versions of MATLAB.
%
% Uncomment the specific line below related to the type of file to be
% processed.
%--------------------------------------------------------------------------
%files = dir(fullfile(dataFolder, 'FILE_NAME -- OR -- *Wildcard.cnt'));
if isfield(cfg, 'searchString') && ~isempty(cfg.searchString)
    searchString = cfg.searchString;
    
else
    searchString = [];
    
end

%--------------------------------------------------------------------------
% Get the type of file to work with:
%--------------------------------------------------------------------------
fileType = cfg.fileType;

if ~isempty(searchString) && ~isfield(cfg, 'doRecursive') || isempty(cfg.doRecursive) || cfg.doRecursive < 1
    files = dir(fullfile(dataFolder, ['*\' searchString '*' fileType]));

elseif ~isempty(searchString) && isfield(cfg, 'doRecursive') && ~isempty(cfg.doRecursive) && cfg.doRecursive > 0
    files = dir(fullfile(dataFolder, ['**\*' searchString '*' fileType]));

elseif isfield(cfg, 'doRecursive') && ~isempty(cfg.doRecursive) && cfg.doRecursive > 0
    files = dir(fullfile(dataFolder, ['**\*' fileType]));
    
else
    files = dir(fullfile(dataFolder, ['*' fileType]));

end
    
    
% 
% switch fileType
%     
% 
% %--------------------------------------------------------------------------
% % If working with native Curry 8 files as CDT:
% %--------------------------------------------------------------------------
%     case '.cdt'
% 
%     if ~isempty(searchString)
%         files = dir(fullfile(dataFolder, ['*' searchString '*' fileType]));
%     else
%         files = dir(fullfile(dataFolder, ['*' fileType]));
%         
%     end
% 
% %--------------------------------------------------------------------------
% % If working with native Curry 7/8 files as CNT:
% %--------------------------------------------------------------------------
%     case '.cnt'
% 
%     if ~isempty(searchString)
%         files = dir(fullfile(dataFolder, ['*' searchString '*' fileType]));
%     else
%         files = dir(fullfile(dataFolder, ['*' fileType]));
%         
%     end
% 
% %--------------------------------------------------------------------------
% % If working with EEGLAB SET files:
% %--------------------------------------------------------------------------
%     case '.set'
% 
%     if ~isempty(searchString)
%         files = dir(fullfile(dataFolder, ['*' searchString '*' fileType]));
%     else
%         files = dir(fullfile(dataFolder, ['*' fileType]));
%         
%     end
% 
% end


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Start an outer loop to begin the processing of all files identified
%$$$$$$ above in files
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
for i = 1:size(files, 1)


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Gather variables to be used later on for I/O operations
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%--------------------------------------------------------------------------
% Old usage:
%--------------------------------------------------------------------------
%[fpath fname fext] = fileparts(f_names{i});

%--------------------------------------------------------------------------
% New implenentation: Get path
%--------------------------------------------------------------------------
fpath = files(i).folder;

%--------------------------------------------------------------------------
% New implenentation: Get file name that should always relate to the
% subject identifier. This removes the ".ext" part.
%--------------------------------------------------------------------------
fname = files(i).name(1:end-4);

%--------------------------------------------------------------------------
% New implenentation: Get the ".ext" part.
%--------------------------------------------------------------------------
fext = files(i).name(end-3:end);

%--------------------------------------------------------------------------
% Perform a "check" to see if the current file has been processed 
% previously. Then determine whether or not to re-process individual files.
%--------------------------------------------------------------------------
reRun = cfg.reRun;
statusFolder = [fpath filesep 'Completed'];
%completeFiles = dir(fullfile(statusFolder, '*.txt'));

filecomplete = fullfile(statusFolder,[fname '-Complete.txt']);
if ~exist(filecomplete, 'file')
    doRun = 1;
    
elseif isfield(cfg, 'reRun') && ~isempty(cfg.reRun) && cfg.reRun > 0
    doRun = 1;
    
else
    doRun = 0;
    
end

%--------------------------------------------------------------------------
% Check for "status complete" flags and exit loop if found, or continue
% processing if reRun is turned on (set to 1):
%--------------------------------------------------------------------------
if reRun == 0 && doRun == 0
fprintf('##################################################################################################################\n\n');
fprintf('Skipping processing of ... %s.\n\n',fname);
fprintf('\n')
fprintf('##################################################################################################################\n\n');    
    
continue

end

%--------------------------------------------------------------------------
% New implenentation: Put everything together to load below.
%--------------------------------------------------------------------------
fload = fullfile(fpath, [fname fext]);


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Load the ith data set. Specify double precision for cnt.
%$$$$$$
%$$$$$$ Catch whether a .cdt, .cnt or .set file
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

fprintf('##################################################################################################################\n\n');
fprintf('Loading data for ... %s.\n\n', fname);
fprintf('##################################################################################################################\n\n');   

switch fileType
    
    case '.cdt'
        EEG = loadcurry(fload, 'CurryLocations', 'True');
    
    case '.cnt'
        EEG = pop_loadcnt(fload, 'dataformat', 'auto', 'precision', 'double');
    
    case '.set'
        EEG = pop_loadset('filename', strcat(fname, fext), 'filepath', fpath);
   
end

%--------------------------------------------------------------------------
% Alternate usage:
%--------------------------------------------------------------------------
% if strcmp(fext,'.cdt')
%     EEG = loadcurry(fload, 'CurryLocations', 'True');
% 
% elseif strcmp(fext,'.cnt')
%     EEG = pop_loadcnt(fload, 'dataformat', 'auto', 'precision', 'double');
% 
% elseif strcmp(fext,'.set')
%     EEG = pop_loadset('filename', strcat(fname, fext), 'filepath', fpath);
%    
% end

%--------------------------------------------------------------------------
% Uncomment to print the contents of the EEG structure:
%--------------------------------------------------------------------------
%EEG = eeg_checkset( EEG )

%--------------------------------------------------------------------------
% Uncomment to update the GUI:
%--------------------------------------------------------------------------
% eeglab redraw


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Resample the data here, if desired, to save HD space and
%$$$$$$ computatinal time.
%$$$$$$
%$$$$$$ Since we'll be doing ICA on epoched data, this is likely not
%$$$$$$ necessary.
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
if isfield(cfg, 'newSampleRate') && ~isempty(cfg.newSampleRate)
    newSampleRate = cfg.newSampleRate;
    
else
    newSampleRate = EEG.srate;
    
end

if EEG.srate ~= newSampleRate
       
    EEG = pop_resample(EEG, newSampleRate);
   
    fprintf('##################################################################################################################\n\n');
    fprintf('Completed resampling for ... %s.\n\n',fname);
    fprintf('##################################################################################################################\n\n');
   
end

%--------------------------------------------------------------------------
% Uncomment to print the contents of the EEG structure:
%--------------------------------------------------------------------------
%EEG = eeg_checkset( EEG )

%--------------------------------------------------------------------------
% Uncomment to update the GUI:
%--------------------------------------------------------------------------
% eeglab redraw


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Make sure EEG.data are in double precision - should not be needed
%$$$$$$ if EEGLAB settngs are correct.
%$$$$$$
%$$$$$$ In the EEGLAB GUI: File / Memory and other options -- uncheck
%$$$$$$ single precision option under memory options to force double
%$$$$$$ precision.
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%--------------------------------------------------------------------------
% Check for double precision:
%--------------------------------------------------------------------------
tmp = EEG.data(1, 1);
tmpinfo = whos('tmp');

%--------------------------------------------------------------------------
% Conditional to correct if caught:
%--------------------------------------------------------------------------
if strcmp(tmpinfo.class, 'double') ~= 1
    %tmpdat = zeros(size(EEG.data));
    tmpdat = double(EEG.data);
    EEG.data = [];
    EEG.data = tmpdat;
   
    clear tmpdat
   
    fprintf('##################################################################################################################\n\n');
    fprintf('Data have been converted to double precision for ... %s. This is a WARNING!!!!!!!\n\n',fname);
    fprintf('Please check that the EEGLAB settings are correct to import in double precision.\n\n');
    fprintf('In the EEGLAB GUI: File / Memory and other options -- uncheck single precision option under\n');
    fprintf('memory options to force double precision.\n\n');
    fprintf('##################################################################################################################\n\n');
   
    %--------------------------------------------------------------------------
    % Uncomment to print the contents of the EEG structure:
    %--------------------------------------------------------------------------
    %EEG = eeg_checkset( EEG )

    %--------------------------------------------------------------------------
    % Uncomment to update the GUI:
    %--------------------------------------------------------------------------
    % eeglab redraw
   
end

clear tmp tmpinfo


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Get rid of channels (EKG, Trigger, etc.) that will not ever be
%$$$$$$ used. For us, these are always the last three in the montage.
%$$$$$$
%$$$$$$ Specify these in the variable chanids. chanids = [67 68 69];
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
if isfield(cfg, 'killchanids') && ~isempty(cfg.killchanids)
    killchanids = cfg.killchanids;

    EEG = pop_select(EEG, 'nochannel', killchanids);
    
end

fprintf('##################################################################################################################\n\n');
fprintf('Completed channel removal for ... %s.\n\n',fname);
fprintf('##################################################################################################################\n\n');

%--------------------------------------------------------------------------
% Uncomment to print the contents of the EEG structure:
%--------------------------------------------------------------------------
%EEG = eeg_checkset( EEG )

%--------------------------------------------------------------------------
% Uncomment to update the GUI:
%--------------------------------------------------------------------------
% eeglab redraw


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Relabel CB* electrodes to OI* electrodes for recognition by lookup
%$$$$$$ tables. These are a very close spatial match.
%$$$$$$
%$$$$$$ Also, rename the HEO and VEO to HEOG and VEOG to comply with
%$$$$$$ widely used nomenclature and lookup tables.
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
for loc = 1:size(EEG.chanlocs,2)
    if strcmpi(EEG.chanlocs(loc).labels, 'CB1') == 1 || strcmpi(EEG.chanlocs(loc).labels, 'I1') == 1
        EEG.chanlocs(loc).labels = 'OI1';
        dolookup = 1;

    elseif strcmpi(EEG.chanlocs(loc).labels, 'CB2') == 1  || strcmpi(EEG.chanlocs(loc).labels, 'I2') == 1
        EEG.chanlocs(loc).labels = 'OI2';
        dolookup = 1;

    elseif strcmpi(EEG.chanlocs(loc).labels, 'HEO') == 1
        EEG.chanlocs(loc).labels = 'HEOG';
        dolookup = 1;
       
    elseif strcmpi(EEG.chanlocs(loc).labels, 'VEO') == 1
        EEG.chanlocs(loc).labels = 'VEOG';
        dolookup = 1;
   
    end

end

fprintf('##################################################################################################################\n\n');
fprintf('If CB electrodes were identified in the montage, they have been relabeled for readability ... %s.\n\n',fname);
fprintf('If VEO and HEO electrodes were identified in the montage, they have also been relabeled for readability ... %s.\n\n',fname);
fprintf('##################################################################################################################\n\n');

%--------------------------------------------------------------------------
% Uncomment to print the contents of the EEG structure:
%--------------------------------------------------------------------------
%EEG = eeg_checkset( EEG )

%--------------------------------------------------------------------------
% Uncomment to update the GUI:
%--------------------------------------------------------------------------
% eeglab redraw


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Relocate referential/bipolar channels so they can be recovered
%$$$$$$ later if necessary.
%$$$$$$
%$$$$$$ If wanted, M1 and M2 (if actually used on the mastoids) can be
%$$$$$$ relabeled as TP9 and TP10 for recognition above.
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%--------------------------------------------------------------------------
% Uncomment to remove M* and *EOG - make sure to match names exactly
% movechanids = {'M1', 'M2', 'VEOG', 'HEOG'};
%--------------------------------------------------------------------------
if isfield(cfg, 'movechanids') && ~isempty(cfg.movechanids)
    movechanids = cfg.movechanids;

    EEG = movechannels(EEG,...
    'Location', 'skipchannels',...
    'Direction', 'Remove',...
    'Channels', movechanids);
    
end

%--------------------------------------------------------------------------
% Just remove M*
%--------------------------------------------------------------------------
% EEG = movechannels(EEG,...
%     'Location', 'skipchannels',...
%     'Direction', 'Remove',...
%     'Channels',{'M1','M2'});

fprintf('##################################################################################################################\n\n');
fprintf('Moved EOG and mastoid channels to EEG.skipchannels so they will not be affected by ICA ... %s.\n\n',fname);
fprintf('##################################################################################################################\n\n');

%--------------------------------------------------------------------------
% Uncomment to print the contents of the EEG structure:
%--------------------------------------------------------------------------
%EEG = eeg_checkset( EEG )

%--------------------------------------------------------------------------
% Uncomment to update the GUI:
%--------------------------------------------------------------------------
% eeglab redraw


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Assign locations for all electrodes:
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
tmpdipfitfolder = dir([eeglabdir filesep 'plugins' filesep 'dipfit*']);
dipfitfolder = fullfile(tmpdipfitfolder(1).folder, tmpdipfitfolder(1).name);
clear tmpdipfitfolder

%--------------------------------------------------------------------------
% Try for a Windows machine:
%--------------------------------------------------------------------------
try EEG = pop_chanedit(EEG, 'lookup',...
    [dipfitfolder '\standard_BESA\standard-10-5-cap385.elp']);

%--------------------------------------------------------------------------
% Catch for Linux and Unix machines:
%--------------------------------------------------------------------------
catch
    EEG = pop_chanedit(EEG, 'lookup',...
    [dipfitfolder '/standard_BESA/standard-10-5-cap385.elp']);

end

fprintf('##################################################################################################################\n\n');
fprintf('Locations have been assigned for all electrodes ... %s.\n\n',fname);
fprintf('##################################################################################################################\n\n');

%--------------------------------------------------------------------------
% Uncomment to print the contents of the EEG structure:
%--------------------------------------------------------------------------
%EEG = eeg_checkset( EEG )

%--------------------------------------------------------------------------
% Uncomment to update the GUI:
%--------------------------------------------------------------------------
% eeglab redraw


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Make sure that the head center is well conditioned for the
%$$$$$$ electrode locations:
%$$$$$$
%$$$$$$ Does not work in eeglab beyond version 14
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
% chanlocs = EEG.chanlocs;
% [chanlocs, ~] = pop_chancenter(chanlocs, [], []);
% 
% EEG = pop_chanedit(EEG, 'eval', 'chans = pop_chancenter( chans, [],[]);');
% 
% fprintf('##################################################################################################################\n\n');
% fprintf('Completed head center optimization for ... %s.\n\n',fname);
% fprintf('##################################################################################################################\n\n');

%--------------------------------------------------------------------------
% Uncomment to print the contents of the EEG structure:
%--------------------------------------------------------------------------
%EEG = eeg_checkset( EEG )

%--------------------------------------------------------------------------
% Uncomment to update the GUI:
%--------------------------------------------------------------------------
% eeglab redraw


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Declare data types for channels:
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%--------------------------------------------------------------------------
% Identify EEG channels:
%--------------------------------------------------------------------------
%EEG = pop_chanedit(EEG, 'settype', {'1:62' 'EEG'});

%--------------------------------------------------------------------------
% Identify EOG channels:
%--------------------------------------------------------------------------
%try EEG = pop_chanedit(EEG, 'settype', {'63:64' 'EOG'});
%   
%catch
%    fprintf('No EOG channels in the array');
%   
%end

%--------------------------------------------------------------------------
% Uncomment to print the contents of the EEG structure:
%--------------------------------------------------------------------------
%EEG = eeg_checkset( EEG )

%--------------------------------------------------------------------------
% Uncomment to update the GUI:
%--------------------------------------------------------------------------
% eeglab redraw


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Run a highpass filter to detrend the data, removing very slow
%$$$$$$ potentials and amplifier drift.
%$$$$$$
%$$$$$$ Syntax: pop_eegfiltnew(EEG, locutoff, hicutoff, filtorder,revfilt, usefft, plotfreqz, minphase)
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
if isfield(cfg, 'hpFilterCut') && ~isempty(cfg.hpFilterCut)
    hpFilterCut = cfg.hpFilterCut;

else
    hpFilterCut = .1;
    
end

%--------------------------------------------------------------------------
% Old format:
%--------------------------------------------------------------------------
%EEG = pop_eegfiltnew(EEG,hpFilterCut,0,[],0,[],0);

%--------------------------------------------------------------------------
% New format:
%--------------------------------------------------------------------------
EEG = pop_eegfiltnew(EEG, [], hpFilterCut, [], true, [], 0);

fprintf('##################################################################################################################\n\n');
fprintf('Completed detrending (high pass filtering) for ... %s.\n\n',fname);
fprintf('##################################################################################################################\n\n');

%--------------------------------------------------------------------------
% Uncomment to print the contents of the EEG structure:
%--------------------------------------------------------------------------
%EEG = eeg_checkset( EEG )

%--------------------------------------------------------------------------
% Uncomment to update the GUI:
%--------------------------------------------------------------------------
% eeglab redraw


%%  
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Run cleanline to reduce line noise if interested in higher 
%$$$$$$ frequency activity. Specify this in maxfreq below:
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
if isfield(cfg, 'maxfreq') && ~isempty(cfg.maxfreq)
    maxfreq = cfg.maxfreq;
    
else
    maxfreq = 40;
    
end

if maxfreq > 55
EEG = pop_cleanline(EEG,...
                    'bandwidth', 2,...
                    'chanlist', [1:EEG.nbchan],...
                    'computepower', 0,...
                    'linefreqs', [60 120 180 240],...
                    'normSpectrum', 0,...
                    'p', 0.01,...
                    'pad', 2,...
                    'plotfigures', 0,...
                    'scanforlines', 1,...
                    'sigtype', 'Channels',...
                    'tau', 100,...
                    'verb', 1,...
                    'winsize', 4,...
                    'winstep', 4);
                
end

fprintf('##################################################################################################################\n\n');
fprintf('Completed cleaning of line noise ... %s.\n\n',fname);
fprintf('##################################################################################################################\n\n');
               
