%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Copy EEG structure to re-use channels for interpolation
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
originalEEG = EEG;


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Clean data using Automatic Subspace Reconstruction (ASR)
%$$$$$$ EEG = clean_rawdata(EEG, arg_flatline, arg_highpass, arg_channel, arg_noisy, arg_burst, arg_window)
%$$$$$$
%$$$$$$ This function removes flatline channels, low-frequency drifts,
%$$$$$$ noisy channels, short-time bursts and incompletely repaird segments
%$$$$$$ from the data. Tip: Any of the core parameters can also be passed
%$$$$$$ in as [] to use the respective default of the underlying functions,
%$$$$$$ or as 'off' to disable it entirely.
%$$$$$$
%$$$$$$ Input               - EEG structure
%$$$$$$
%$$$$$$ Out
%$$$$$$                     - EEG: Final cleaned EEG recording.
%$$$$$$
%$$$$$$                     - HP: Optionally just the high-passed data.
%$$$$$$
%$$$$$$                     - BUR: Optionally the data without final
%$$$$$$                       removal of "irrecoverable" windows.
%$$$$$$
%$$$$$$ FlatlineCriterion   - Maximum tolerated flatline duration (in sec).
%$$$$$$                       If a channel has a longer flatline than this,
%$$$$$$                       it will be considered abnormal. Default: 5
%$$$$$$ Highpass            - Transition band for the initial high-pass
%$$$$$$                       filter in Hz. This is formatted as
%$$$$$$                       [transition-start, transition-end].
%$$$$$$                       Default: [0.25 0.75].
%$$$$$$ ChannelCriterion    - Minimum channel correlation. If a channel is
%$$$$$$                       correlated at less than this value to a
%$$$$$$                       reconstruction of it based on other channels,
%$$$$$$                       it is considered abnormal in the given time
%$$$$$$                       window. This method requires that channel
%$$$$$$                       locations are available and roughly correct;
%$$$$$$                       otherwise a fallback criterion will be used.
%$$$$$$                       Default: 0.85
%$$$$$$ LineNoiseCriterion  - If a channel has more line noise relative to
%$$$$$$                       its signal than this value, in standard
%$$$$$$                       deviations based on the total channel
%$$$$$$                       population, it is considered abnormal.
%$$$$$$                       Default: 4
%$$$$$$ BurstCriterion      - Standard deviation cutoff for removal of
%$$$$$$                       bursts (via ASR). Data portions whose
%$$$$$$                       variance is larger than this threshold
%$$$$$$                       relative to the calibration data are
%$$$$$$                       considered missing data and will be removed.
%$$$$$$                       The most aggressive value that can be used
%$$$$$$                       without losing much EEG is 3. It is
%$$$$$$                       recommended to at first visually inspect the
%$$$$$$                       difference between the original and cleaned
%$$$$$$                       data to get a sense of the removed content at
%$$$$$$                       various levels. A quite conservative value
%$$$$$$                       is 5. Default: 5.
%$$$$$$ WindowCriterion     - Criterion for removing time windows that were
%$$$$$$                       not repaired completely. This may happen if
%$$$$$$                       the artifact in a window was composed of too
%$$$$$$                       many simultaneous uncorrelated sources (for
%$$$$$$                       example, extreme movements such as jumps).
%$$$$$$                       This is the maximum fraction of contaminated
%$$$$$$                       channels that are tolerated in the final
%$$$$$$                       output data for each considered window.
%$$$$$$                       Generally a lower value makes the criterion
%$$$$$$                       more aggressive. Default: 0.25. Reasonable
%$$$$$$                       range: 0.05 (aggressive) to 0.3 (lax).
%$$$$$$ MaxMem              - The maximum amount of memory in MB used by
%$$$$$$                       the algorithm when processing. See function
%$$$$$$                       asr_processf for more information. Default
%$$$$$$                       is 64 MB.
%$$$$$$
%$$$$$$ Old Syntax: EEG = clean_rawdata(EEG, arg_flatline, arg_highpass, arg_channel, arg_noisy, arg_burst, arg_window)
%$$$$$$ New Syntax: [EEG,HP,BUR] = clean_artifacts(EEG, Options...)
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%--------------------------------------------------------------------------
% clean_rawdata is now depricated:
%--------------------------------------------------------------------------
%EEG = clean_rawdata(EEG, -1, -1, 0.8, -1, 8, 0.25);

%--------------------------------------------------------------------------
% clean_artifacts is the current implementation:
%--------------------------------------------------------------------------
if isfield(cfg, 'doASR') && ~isempty(cfg.doASR)
    doASR = cfg.doASR;
    
else
    doASR = 0;
    
end

if doASR ~= 0
EEG = clean_artifacts(EEG,...
                            'ChannelCriterion', 0.85,...
                            'LineNoiseCriterion', 4,...
                            'BurstCriterion', 5,...
                            'WindowCriterion', 0.275,...
                            'Highpass', [],...
                            'FlatlineCriterion', 5,...
                            'BurstRejection', 'off',...
                            'Distance', 'euclidian',...
                            'MaxMem', 8192);
end

fprintf('##################################################################################################################\n\n');
fprintf('Completed cleaning of artifacts with ASR ... %s.\n\n',fname);
fprintf('##################################################################################################################\n\n');

