%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Create a redundant copy of EEG to pull epoched data from while
%$$$$$$ maintaining the properties of the newly-cleaned data
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
cleanEEG = EEG;


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ There are good reasons to epoch data prior to calculating power,
%$$$$$$ or anything else based on frequency - even for a continuous data 
%$$$$$$ set.
%$$$$$$
%$$$$$$ 1) Averaging over segments (epochs) has the tendency to stabilize
%$$$$$$ the measurement of interest
%$$$$$$
%$$$$$$ 2) You have the option to keep "time" in the picture if desired.
%$$$$$$
%$$$$$$ This will insert pseudo event markers in the dataset, but will not
%$$$$$$ do any sort of epoching - can be done later. These events are
%$$$$$$ indicated with a '1'.
%$$$$$$
%$$$$$$ There are also good reasons for leaving things alone, which is what
%$$$$$$ will do here. For a normal power analysis, you don't have time as a
%$$$$$$ consideration, so we'll go without it for now (just insert events).
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

if isfield(cfg,'continuous') && ~isempty(cfg.continuous)
    continuous = cfg.continuous;
    
else
    continuous = 0;
    
end

if continuous >= 1
    if isfield(cfg, 'addEvents') && ~isempty(cfg.addEvents)
        addEvents = cfg.addEvents;

    else
        addEvents = 0;

    end

    if addEvents > 0
        if isfield(cfg, 'contEpLeng') && ~isempty(cfg.contEpLeng)
            contEpLeng = cfg.contEpLeng;
        
        else
            contEpElng = 2;
            
        end
        
        %EEG = eeg_regepochs(EEG, 'recurrence', floor((EEG.pnts/1000) *.010), 'limits', [0 floor((EEG.pnts/1000) *.010)], 'eventtype', '1', 'extractepochs', 'off');
        EEG = eeg_regepochs(EEG, 'recurrence', contEpElng, 'eventtype', '1', 'extractepochs', 'off', 'rmbase', NaN);
        
fprintf('##################################################################################################################\n\n');
fprintf('Added events into the continuous data set ... %s.\n\n', fname);
fprintf('##################################################################################################################\n\n');

    end

end

%--------------------------------------------------------------------------
% Alternate implementation:
%--------------------------------------------------------------------------
% EEG = eeg_regepochs(EEG, 'recurrence', 5, 'limits', [0 5], 'eventtype', '1', 'extractepochs', 'off');
% EEG = eeg_checkset(EEG);
% eeglab redraw

%--------------------------------------------------------------------------
% Sanity check: to remove all event markers
%--------------------------------------------------------------------------
% Delete events with type name '1'
% allEvents = {EEG.event.type}';
% example1Idx = strcmp(allEvents, '1');
% EEG.event(example1Idx) = [];
% eeglab redraw


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Identify condition names (for I/O) and their event numbers to be
%$$$$$$ used in the epoching process.
%$$$$$$
%$$$$$$ Both vectors below are directly related to each unique experiment.
%$$$$$$
%$$$$$$ Both conds and condnumbers must have the same number of entries.
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%--------------------------------------------------------------------------
% For condition-specific file I/O:
%--------------------------------------------------------------------------
% conds = {'EEG_2', 'EEG_4', 'EEG_8', 'EEG_16', 'EEG_32', 'EEG_64'};

%--------------------------------------------------------------------------
% These are embedded code conditions. Every different study will be unique.
%
% To hard code event markers:
%--------------------------------------------------------------------------
%evmarkers = [2, 4, 8, 16, 32, 64];
if isfield(cfg, 'evmarkers') || ~isempty(cfg.evmarkers)
    evmarkers = cfg.evmarkers;

elseif ~isfield(cfg, 'evmarkers') || isempty(cfg.evmarkers)
    %evmarkers = cfg.evmarkers;
%--------------------------------------------------------------------------
% Automatically find conditions/event markers. This is good for 
% event-related data and also continuous data with pseudo-event markers 
% inserted above:
%--------------------------------------------------------------------------
    tmp = EEG.event(1).type;
    tmpinfo = whos('tmp');

%--------------------------------------------------------------------------
% Conditional to correct if caught:
%--------------------------------------------------------------------------
    if strcmp(tmpinfo.class, 'double') ~= 1

        if size(EEG.event,2) > 0
            for numconds = 1:size(EEG.event, 2)
                tmpevmarkers{numconds} = EEG.event(numconds).type;

            end

        end

    elseif strcmp(tmpinfo.class, 'double') == 1

        if size(EEG.event, 2) > 0
            for numconds = 1:size(EEG.event, 2)
                tmpevmarkers(numconds) = EEG.event(numconds).type;

            end

        end

    end

    if strcmp(tmpinfo.class,'double') ~= 1
        tmpevmarkers = str2num(tmpevmarkers);
        tmpevmarkers = double(tmpevmarkers);

    end

    evmarkers = unique(tmpevmarkers);

%--------------------------------------------------------------------------
% Check for event markers to remove:
%--------------------------------------------------------------------------
    if isfield(cfg, 'killevmarkers') && ~isempty(cfg.killevmarkers)
        killevmarkers = cfg.killevmarkers;
        
    end
    
    if exist('killevmarkers', 'var')
        for k = 1:length(killevmarkers)
            evmarkers = evmarkers(evmarkers ~= killevmarkers(k));
            
        end
            
    end

%--------------------------------------------------------------------------
% Otherwise, use supplied event markers:
%--------------------------------------------------------------------------
%elseif isfield(cfg, 'evmarkers') || ~isempty(cfg.evmarkers)
    %evmarkers = cfg.evmarkers;
    
end

%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Cut epochs based on individual conditions for ICA decomposition.
%$$$$$$
%$$$$$$ These should be longer in duration as compared to your eventual
%$$$$$$ epochs used for analysis.
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%--------------------------------------------------------------------------
% Epoch start (time 0 is stimulus onset): epstart = -3;
%--------------------------------------------------------------------------
if isfield(cfg, 'epstart') && ~isempty(cfg.epstart)
    epstart = cfg.epstart;
    
end

%--------------------------------------------------------------------------
% Epoch end (time 0 is stimulus onset): epend = 3;
%--------------------------------------------------------------------------
if isfield(cfg, 'epend') && ~isempty(cfg.epend)
    epend = cfg.epend;
    
end

%--------------------------------------------------------------------------
% Cut the epochs:
%--------------------------------------------------------------------------
if exist('epstart', 'var') && exist('epend', 'var')
    if isnumeric(evmarkers) == 1
        EEG = pop_epoch(EEG, num2cell(evmarkers), [epstart epend]);

    else
        EEG = pop_epoch(EEG, evmarkers, [epstart epend]);

    end

end

fprintf('##################################################################################################################\n\n');
fprintf('Data have been epoched at [%f - %f], keeping all conditions ... %s.\n\n', epstart, epend, fname);
fprintf('##################################################################################################################\n\n');

%--------------------------------------------------------------------------
% Uncomment to print the contents of the EEG structure:
%--------------------------------------------------------------------------
%EEG = eeg_checkset( EEG )

%--------------------------------------------------------------------------
% Uncomment to update the GUI:
%--------------------------------------------------------------------------
% eeglab redraw

%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Get ready for ICA
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$


%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Estimate the rank of the data. If cleanrawdata (above) dropped a
%$$$$$$ channel that was later interpolated, it does not carry independent
%$$$$$$ information and cannot be used in ICA reconstruction.
%$$$$$$
%$$$$$$ ICA is a linear decomposition method that aims at generating the
%$$$$$$ maximally temporally independent signals available in the channel
%$$$$$$ data. If the data are full rank (i.e., no channel can be expressed
%$$$$$$ as a linear combination of other channels), then the number of
%$$$$$$ independent components (ICs) is the same as the number of channels.
%$$$$$$
%$$$$$$ Otherwise, if the data are rank deficient, then the number of ICs
%$$$$$$ should be equal to the data rank.
%$$$$$$
%$$$$$$ Interpolating bad channels or average re-referencing are common
%$$$$$$ operations that could make the data rank deficient.
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
dataRank = rank(double(cleanEEG.data'));

%--------------------------------------------------------------------------
% Check for interpolated channels from ASR:
%--------------------------------------------------------------------------
if isfield(cleanEEG.etc, 'clean_channel_mask')
    dataRank = min([rank(double(cleanEEG.data')) sum(cleanEEG.etc.clean_channel_mask)]);

end

%--------------------------------------------------------------------------
% Check for average reference:
%--------------------------------------------------------------------------
if strcmp(EEG.ref,'averef')
    dataRank = dataRank - 1;
   
end


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ This section takes care of ICA decomposition.
%$$$$$$
%$$$$$$ The  EEG  is  composed  of  electrical  potentials  arising  from
%$$$$$$ several  sources.  Each  source (including separate neural
%$$$$$$ clusters, blink artifact, or pulse artifact) projects a unique
%$$$$$$ topography onto the scalp a.k.a. 'scalp maps'. These maps are
%$$$$$$ mixed according to the principle of linear superposition.
%$$$$$$
%$$$$$$ Independent component analysis (ICA) attempts to reverse the
%$$$$$$ superposition by separating the EEG into mutually independent scalp
%$$$$$$ maps, or components.
%$$$$$$
%$$$$$$ Independent Component Analysis is a signal processing method to
%$$$$$$ separate independent sources linearly mixed in several sensors. For
%$$$$$$ instance, when recording electroencephalograms (EEG) on the scalp,
%$$$$$$ ICA can separate out neural signals from artifacts embedded in the
%$$$$$$ data (since they are usually independent of each other).
%$$$$$$
%$$$$$$ EEGLAB has several algorithms that can be used to achieve this.
%$$$$$$ Each has unique strengths and weaknesses, and so I have coded most
%$$$$$$ of the popular ones below.
%$$$$$$
%$$$$$$ Declare your ICA method of interest according to the following:
%$$$$$$ AMICA: ICAtype = 1;
%$$$$$$ Infomax: ICAtype = 2;
%$$$$$$ SOBI: ICAtype = 3;
%$$$$$$ JADE: ICAtype = 4;
%$$$$$$ PICARD: ICAtype = 5;
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%--------------------------------------------------------------------------
% Set flag to do/not do ICA:
%--------------------------------------------------------------------------
if isfield(cfg, 'doICA') && ~isempty(cfg.doICA)
    doICA = cfg.doICA;
    
else
    doICA = 0;
    
end

%--------------------------------------------------------------------------
% Evaluate flag:
%--------------------------------------------------------------------------
if doICA > 0

%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Set ICA algorithm:
%$$$$$$ AMICA: ICAtype = 1;
%$$$$$$ Infomax: ICAtype = 2;
%$$$$$$ SOBI: ICAtype = 3;
%$$$$$$ JADE: ICAtype = 4;
%$$$$$$ PICARD: ICAtype = 5; (Default)
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
if isfield(cfg, 'ICAtype') && ~isempty(cfg.ICAtype)
    ICAtype = cfg.ICAtype;
    
else
    ICAtype = 5;
    
end


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Evaluate request and execute ICA
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
switch ICAtype
   

%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$$$$$ For AMICA:
%$$$$$$ AMICA installation instructions for Windows:
%$$$$$$ https://sccn.ucsd.edu/wiki/Makoto%27s_preprocessing_pipeline#Run_ICA_.2801.2F20.2F2017_updated.29
%$$$$$$ For troubleshooting, see the AMICA documentation (SCCN).
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$  
case 1

%--------------------------------------------------------------------------
% Set AMICA output path:
%--------------------------------------------------------------------------
AMICAout = [ pwd filesep 'amicaout' filesep fname ];
if ~exist('AMICAout','dir') == 1
    mkdir(char(AMICAout))
   
end

%--------------------------------------------------------------------------
% Move to the output directory to manage floating temporary files:
%--------------------------------------------------------------------------
cwd = pwd;
cd(AMICAout)

%--------------------------------------------------------------------------
% Run AMICA:
%--------------------------------------------------------------------------
runamica15(EEG.data,...
    'num_chans', EEG.nbchan,...
    'outdir', [ AMICAout ],...
    'pcakeep', dataRank,...
    'num_models', 1,...
    'do_reject', 1,...
    'numrej', 3,...
    'rejsig', 3,...
    'rejstart', 3,...
    'rejint', 3,...
    'max_iter', 5000,...
    'max_threads', 16);

%--------------------------------------------------------------------------
% Move back over to the previous directory:
%--------------------------------------------------------------------------
cd(cwd)

%--------------------------------------------------------------------------
% Load results of AMICA to be used in subsequent processng steps:
%--------------------------------------------------------------------------
AMICAin = fullfile(AMICAout);
EEG.etc.amica = loadmodout15([ AMICAin ]);
EEG.etc.amica.S = EEG.etc.amica.S(1:EEG.etc.amica.num_pcs, :);
EEG.icaweights = EEG.etc.amica.W;
EEG.icasphere  = EEG.etc.amica.S;

%--------------------------------------------------------------------------
% To manually calculate the ICA activations:
%--------------------------------------------------------------------------
EEG.icaact = (EEG.icaweights*EEG.icasphere)*EEG.data(:,:);
EEG.icaact = reshape( EEG.icaact, size(EEG.icaact,1), EEG.pnts, EEG.trials);
EEG.icawinv = pinv(EEG.icaweights*EEG.icasphere);
EEG.icachansind = [1:EEG.nbchan];

%--------------------------------------------------------------------------
% To let EEGLAB calculate the ICA activations:
%--------------------------------------------------------------------------
%EEG = eeg_checkset(EEG, 'ica')

fprintf('##################################################################################################################\n\n');
fprintf('ICA (AMICA) completed for ... %s.\n\n',fname);
fprintf('##################################################################################################################\n\n');

%--------------------------------------------------------------------------
% Uncomment to print the contents of the EEG structure:
%--------------------------------------------------------------------------
%EEG = eeg_checkset( EEG )

%--------------------------------------------------------------------------
% Uncomment to update the GUI:
%--------------------------------------------------------------------------
% eeglab redraw


%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$$$$$ For Infomax:
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$    
case 2
   
%--------------------------------------------------------------------------
% Directly call the Infomax algorithm:
% Keeping the number of components as determined above
% Learning rate lowered to 1e-8
%--------------------------------------------------------------------------
EEG = pop_runica(EEG,...
                'icatype', 'runica',...
                'extended', 1,...
                'pca', dataRank,...
                'stop', 1e-7,...
                'interupt','off');

%--------------------------------------------------------------------------
% To manually calculate the ICA activations:
%--------------------------------------------------------------------------
EEG.icaact = (EEG.icaweights*EEG.icasphere)*EEG.data(:,:);
EEG.icaact = reshape( EEG.icaact, size(EEG.icaact,1), EEG.pnts, EEG.trials);
EEG.icawinv = pinv(EEG.icaweights*EEG.icasphere);
EEG.icachansind = [1:EEG.nbchan];

%--------------------------------------------------------------------------
% To let EEGLAB calculate the ICA activations:
%--------------------------------------------------------------------------
%EEG = eeg_checkset(EEG, 'ica')

fprintf('##################################################################################################################\n\n');
fprintf('ICA (Infomax) completed for ... %s.\n\n',fname);
fprintf('##################################################################################################################\n\n');

%--------------------------------------------------------------------------
% Uncomment to print the contents of the EEG structure:
%--------------------------------------------------------------------------
%EEG = eeg_checkset( EEG )

%--------------------------------------------------------------------------
% Uncomment to update the GUI:
%--------------------------------------------------------------------------
% eeglab redraw

%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$$$$$ For SOBI:
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$    
case 3
   
%--------------------------------------------------------------------------
% Directly call the SOBI algorithm:
% Use all defaults.
%--------------------------------------------------------------------------
EEG = pop_runica(EEG, 'icatype', 'sobi');

%--------------------------------------------------------------------------
% To manually calculate the ICA activations:
%--------------------------------------------------------------------------
EEG.icaact = (EEG.icaweights*EEG.icasphere)*EEG.data(:,:);
EEG.icaact = reshape( EEG.icaact, size(EEG.icaact,1), EEG.pnts, EEG.trials);
EEG.icawinv = pinv(EEG.icaweights*EEG.icasphere);
EEG.icachansind = [1:EEG.nbchan];

%--------------------------------------------------------------------------
% To let EEGLAB calculate the ICA activations:
%--------------------------------------------------------------------------
%EEG = eeg_checkset(EEG, 'ica')

fprintf('##################################################################################################################\n\n');
fprintf('ICA (SOBI) completed for ... %s.\n\n',fname);
fprintf('##################################################################################################################\n\n');

%--------------------------------------------------------------------------
% Uncomment to print the contents of the EEG structure:
%--------------------------------------------------------------------------
%EEG = eeg_checkset( EEG )

%--------------------------------------------------------------------------
% Uncomment to update the GUI:
%--------------------------------------------------------------------------
% eeglab redraw


%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$$$$$ For JADE:
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$    
case 4
   
%--------------------------------------------------------------------------
% Directly call the JADE algorithm:
% Use all defaults.
%--------------------------------------------------------------------------
EEG = pop_runica(EEG, 'icatype', 'jader');

%--------------------------------------------------------------------------
% To manually calculate the ICA activations:
%--------------------------------------------------------------------------
EEG.icaact = (EEG.icaweights*EEG.icasphere)*EEG.data(:,:);
EEG.icaact = reshape( EEG.icaact, size(EEG.icaact,1), EEG.pnts, EEG.trials);
EEG.icawinv = pinv(EEG.icaweights*EEG.icasphere);
EEG.icachansind = [1:EEG.nbchan];

%--------------------------------------------------------------------------
% To let EEGLAB calculate the ICA activations:
%--------------------------------------------------------------------------
%EEG = eeg_checkset(EEG, 'ica')

fprintf('##################################################################################################################\n\n');
fprintf('ICA (JADE) completed for ... %s.\n\n',fname);
fprintf('##################################################################################################################\n\n');

%--------------------------------------------------------------------------
% Uncomment to print the contents of the EEG structure:
%--------------------------------------------------------------------------
%EEG = eeg_checkset( EEG )

%--------------------------------------------------------------------------
% Uncomment to update the GUI:
%--------------------------------------------------------------------------
% eeglab redraw

%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$$$$$ For PICARD:
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$    
case 5
   
%--------------------------------------------------------------------------
% Directly call the PICARD algorithm:
% Use all defaults.
%--------------------------------------------------------------------------
EEG = pop_runica(EEG, 'icatype', 'picard', 'mode', 'ortho', 'maxiter', 200, 'tol', 1e-10, 'verbose', 1);

%--------------------------------------------------------------------------
% To manually calculate the ICA activations:
%--------------------------------------------------------------------------
EEG.icaact = (EEG.icaweights*EEG.icasphere)*EEG.data(:,:);
EEG.icaact = reshape( EEG.icaact, size(EEG.icaact,1), EEG.pnts, EEG.trials);
EEG.icawinv = pinv(EEG.icaweights*EEG.icasphere);
EEG.icachansind = [1:EEG.nbchan];

%--------------------------------------------------------------------------
% To let EEGLAB calculate the ICA activations:
%--------------------------------------------------------------------------
%EEG = eeg_checkset(EEG, 'ica')

fprintf('##################################################################################################################\n\n');
fprintf('ICA (PICARD) completed for ... %s.\n\n',fname);
fprintf('##################################################################################################################\n\n');

%--------------------------------------------------------------------------
% End Case/Switch for ICAtype:
%--------------------------------------------------------------------------
end

%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ This section works to automatically classify ICA components as
%$$$$$$ either brain or artifact (eye, muscle, line noise, etc.).
%$$$$$$
%$$$$$$ There are several toolboxes available for this, with ICLabel,
%$$$$$$ SASICA, MARA, and ADJUST being some of the newer / more popular
%$$$$$$ ones. So I have coded most of these below.
%$$$$$$
%$$$$$$ Declare your classification method of interest according to the
%$$$$$$ following:
%$$$$$$ ICLabel: CLASStype = 1;
%$$$$$$ SASICA: CLASStype = 2;
%$$$$$$ MARA: CLASStype = 3;
%$$$$$$ ADJUST: CLASStype = 4;
%$$$$$$
%$$$$$$ There is also the possibility to remove components that are likely
%$$$$$$ to be artifactual. If we do this, I prefer an automated method to
%$$$$$$ remove the potential for human error/bias. If components are/are
%$$$$$$ not to be eomved, set/unset the removeComponents flag below:
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
if isfield(cfg, 'classifyComponents') && ~isempty(cfg.classifyComponents)
    classifyComponents = cfg.classifyComponents;
    
else
    classifyComponents = 0;
    
end

if isfield(cfg, 'removeComponents') && ~isempty(cfg.removeComponents)
    removeComponents = cfg.removeComponents;
    
else
    removeComponents = 0;
    
end

if classifyComponents > 0
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Set classification algorithm:
%$$$$$$ ICLabel: CLASStype = 1;
%$$$$$$ SASICA: CLASStype = 2;
%$$$$$$ MARA: CLASStype = 3;
%$$$$$$ ADJUST: CLASStype = 4;
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
if isfield(cfg, 'CLASStype') && ~isempty(cfg.CLASStype)
    CLASStype = cfg.CLASStype;
    
else
    CLASStype = 1;
    
end

%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Evaluate request and execute ICA-based rejection
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
switch CLASStype


%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$$$$$ For ICLabel:
%$$$$$$ Potential classes:
%$$$$$$ 'Brain' 'Muscle' 'Eye' 'Heart' 'Line Noise' 'Channel Noise' 'Other'
%$$$$$$
%$$$$$$ For each component classification, there is an associated %
%$$$$$$ likelihood of membership to that class
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$  
case 1

%--------------------------------------------------------------------------
% Directly call the ICLabel algorithm:
%--------------------------------------------------------------------------
EEG = pop_iclabel(EEG, 'default');


%--------------------------------------------------------------------------
% Gather and sort classes based on their likelihood of membership,
% retaining the strength of each class:
%--------------------------------------------------------------------------
for c = 1:size(EEG.etc.ic_classification.ICLabel.classifications)
   
    [str, ic_class] = max(EEG.etc.ic_classification.ICLabel.classifications(c,:));
    classification(c, 1) = ic_class;
    classification(c, 2) = str;

end

%--------------------------------------------------------------------------
% Split classes into brain and nonbrain, keeping only the brain components
% that are more likely than chance (60%):
%--------------------------------------------------------------------------
brain = find(classification(:,1) == 1 & classification(:,2) > .6)';
nonbrain = setdiff(1:size(classification,1), brain);

%--------------------------------------------------------------------------
% Add brain/nonbrain ICs to the ICLabel field in EEG:
%--------------------------------------------------------------------------
EEG.etc.ic_classification.ICLabel.brain = brain;
EEG.etc.ic_classification.ICLabel.nonbrain = nonbrain;

fprintf('##################################################################################################################\n\n');
fprintf('ICLabel artifact identification complete ... %s.\n\n',fname);
fprintf('##################################################################################################################\n\n');

%--------------------------------------------------------------------------
% Check for component removal and execute if selected:
%--------------------------------------------------------------------------
if removeComponents > 0
EEG = pop_subcomp(EEG, nonbrain, 1);

fprintf('##################################################################################################################\n\n');
fprintf('EEG data artifcats pruned with ICLabel ... %s.\n\n',fname);
fprintf('##################################################################################################################\n\n');


end


%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$$$$$ For SASICA:
%$$$$$$
%$$$$$$ TODO
%$$$$$$ To be done - think about including *EOG for SASICA classification
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$    
case 2
   
%--------------------------------------------------------------------------
% Directly call the SASICA algorithm:
%--------------------------------------------------------------------------
EEG_ICA = eeg_SASICA(EEG,...
    'MARA_enable',0,...
    'FASTER_enable',0,...
    'FASTER_blinkchanname','VEOG',...
    'ADJUST_enable',1,...
    'chancorr_enable',0,...
    'chancorr_channames','No channel',...
    'chancorr_corthresh','auto 4',...
    'EOGcorr_enable',0,...
    'EOGcorr_Heogchannames','HEOG',...
    'EOGcorr_corthreshH','auto 4',...
    'EOGcorr_Veogchannames','VEOG',...
    'EOGcorr_corthreshV','auto 4',...
    'resvar_enable',0,...
    'resvar_thresh',15,...
    'SNR_enable',0,...
    'SNR_snrcut',1,...
    'SNR_snrBL',[-Inf 0] ,...
    'SNR_snrPOI',[0 Inf] ,...
    'trialfoc_enable',1,...
    'trialfoc_focaltrialout','auto',...
    'focalcomp_enable',1,...
    'focalcomp_focalICAout','auto',...
    'autocorr_enable',1,...
    'autocorr_autocorrint',20,...
    'autocorr_dropautocorr','auto',...
    'opts_noplot',1,...
    'opts_nocompute',0,...
    'opts_FontSize',14);
 
fprintf('##################################################################################################################\n\n');
fprintf('SASICA artifact identification complete ... %s.\n\n',fname);
fprintf('##################################################################################################################\n\n');

%--------------------------------------------------------------------------
% Copy the ICA weights and spheres and SASICA rejections to the main
% (non-ICA) data set. EEG.icaact should not be copied from the ICA dataset
% to the main one, for the number of data points is different (because of
% pre-ICA cleanup). Instead, copy the weights and spheres, and calculate
% the activations for the main data
%--------------------------------------------------------------------------
EEG.icawinv = EEG_ICA.icawinv;
EEG.icasphere = EEG_ICA.icasphere;
EEG.icaweights = EEG_ICA.icaweights;
EEG.icachansind = EEG_ICA.icachansind;

%--------------------------------------------------------------------------
% Prepare for matrix manipulation to transfer over icaact
% Get dimensions of EEG.data and EEG.icaact to reshape
%--------------------------------------------------------------------------
dims = size(EEG.data);
idims = size(EEG.icaact);


%--------------------------------------------------------------------------
% Do the reshaping
%--------------------------------------------------------------------------
EEG.data = reshape(EEG.data,[dims(1),dims(2)*dims(3)]);
EEG.icaact = reshape(EEG.icaact,[idims(1),idims(2)*idims(3)]);


%--------------------------------------------------------------------------
% Do the transfer via matrix multiplication
%--------------------------------------------------------------------------
%EEG.icaact = (EEG.icaweights*EEG.icasphere).*EEG.data(EEG.icachansind);
EEG.icaact = (EEG.icaweights*EEG.icasphere)*EEG.data(EEG.icachansind,:);

% Alternative usage:
% comp = 1:size(EEG.icaweights,1);
% icaact = (EEG.icaweights(comp,:)*EEG.icasphere)*reshape(EEG.data(EEG.icachansind,:,:), length(EEG.icachansind), EEG.trials*EEG.pnts);
% EEG.icaact = reshape(icaact, size(icaact,1), EEG.pnts, EEG.trials);


%--------------------------------------------------------------------------
% Reshape back to epoched format
%--------------------------------------------------------------------------
EEG.data = reshape(EEG.data,[dims(1),dims(2),dims(3)]);
EEG.icaact = reshape(EEG.icaact,[idims(1),idims(2),idims(3)]);
%eeglab redraw


%--------------------------------------------------------------------------
% Check for removal of artifact components
%--------------------------------------------------------------------------
if removeComponents > 0

%--------------------------------------------------------------------------
% Extract the Component numbers to remove from the output of SASICA
% in EEG.reject.gcompreject.  Wherever this is 1, that particular
% ICA component needs to be removed from the data.
%--------------------------------------------------------------------------
EEG.reject.gcompreject = EEG_ICA.reject.gcompreject;
EEG.reject.SASICA = EEG_ICA.reject.SASICA;
remComps = find(EEG.reject.gcompreject == 1);
%eeglab redraw

%--------------------------------------------------------------------------
% Remove the components
% Use EEG = pop_subcomp(EEG, Components_to_remove, 1) to ask for
% confirmation and visualise the difference that the removals would
% make to the data
%--------------------------------------------------------------------------
EEG = pop_subcomp(EEG, remComps);
eeglab redraw

fprintf('##################################################################################################################\n\n');
fprintf('EEG data artifcats pruned with SASICA ... %s.\n\n',fname);
fprintf('##################################################################################################################\n\n');

end


%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ For MARA:
%$$$$$$
%$$$$$$ Inputs and Outputs:
%$$$$$$   ALLEEG     - array of EEG dataset structures
%$$$$$$   EEG        - current dataset structure or structure array
%$$$$$$              (EEG.reject.gcompreject will be updated)  
%$$$$$$   CURRENTSET - index(s) of the current EEG dataset(s) in ALLEEG
%$$$$$$
%$$$$$$
%$$$$$$ Optional Input:
%$$$$$$ options     - 1x5 array specifing optional operations, default is [0,0,0,0,0]
%$$$$$$             - option(1) = 1 => filter the data before MARA classification
%$$$$$$             - option(2) = 1 => run ica before MARA classification
%$$$$$$             - option(3) = 1 => plot components to label them for rejection after MARA classification
%$$$$$$                                (for rejection)
%$$$$$$             - option(4) = 1 => plot MARA features for each IC
%$$$$$$             - option(5) = 1 => automatically reject MARA's artifactual
%$$$$$$                                 components without inspecting them
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$    
case 3

%--------------------------------------------------------------------------
% To ONLY CLASSIFY with MARA, uncomment here:
%--------------------------------------------------------------------------
if removeComponents == 0
[ALLEEG, EEG, CURRENTSET] = processMARA(ALLEEG, EEG, CURRENTSET,[0,0,0,0,0]);

%--------------------------------------------------------------------------
% Directly call the MARA algorithm, with the artifact flag included:
%--------------------------------------------------------------------------
elseif removeComponents > 0
[ALLEEG, EEG, CURRENTSET] = processMARA(ALLEEG, EEG, CURRENTSET,[0,0,0,0,1]);

fprintf('##################################################################################################################\n\n');
fprintf('EEG data artifcats identified and pruned with MARA ... %s.\n\n',fname);
fprintf('##################################################################################################################\n\n');

end


%--------------------------------------------------------------------------
% End case/switch for ICA classification:
%--------------------------------------------------------------------------
end

%--------------------------------------------------------------------------
% End conditional for ICA classification:
%--------------------------------------------------------------------------
end

%--------------------------------------------------------------------------
% End Conditional for ICA Calculation:
%--------------------------------------------------------------------------
end


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Get ready for condition splits
%$$$$$$
%$$$$$$ Make another copy of the EEG structure
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
allcondsEEG = EEG;


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Start a loop across the conditions, if more than one:  
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
for ii = 1:size(evmarkers,2)

%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Cut epochs based on individual conditions for further processing
%$$$$$$
%$$$$$$ Here, epochs are split into independent condition and are truncated
%$$$$$$ around the event onset
%$$$$$$
%$$$$$$ All ICA information is transferred to the individual condition data
%$$$$$$ sets
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%--------------------------------------------------------------------------
% Define new epoch limits if wanted:
%--------------------------------------------------------------------------
if isfield(cfg, 'newepstart') && ~isempty(cfg.newepstart)
    newepstart = cfg.newepstart;
    
end

if isfield(cfg, 'newepend') && ~isempty(cfg.newepend)
    newepend = cfg.newepend;
    
end

%--------------------------------------------------------------------------
% Extract new epochs (if found to be different):
%--------------------------------------------------------------------------
if exist('newepstart','var') && exist('newepend', 'var')
    if size(allcondsEEG.data,2) ~= abs(diff([newepend newepstart])) * allcondsEEG.srate

        if isnumeric(evmarkers) == 1
        EEG = pop_epoch( allcondsEEG, {  num2str(evmarkers(ii))  }, [newepstart newepend] );

        else
        EEG = pop_epoch( allcondsEEG, evmarkers(ii), [newepstart newepend] );

        end

    end

end

%--------------------------------------------------------------------------
% Uncomment to print the contents of the EEG structure:
%--------------------------------------------------------------------------
% EEG = eeg_checkset( EEG )

%--------------------------------------------------------------------------
% Uncomment to update the GUI:
%--------------------------------------------------------------------------
% eeglab redraw


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Remove baseline differences from the epochs
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
if isfield(cfg, 'baselength') && ~isempty(cfg.baselength)
    baselength = cfg.baselength;
    EEG = pop_rmbase(EEG, [EEG.xmin EEG.xmin + baselength]);
    
else
    baselength = [];
    EEG = pop_rmbase(EEG, baselength);

    
end



%--------------------------------------------------------------------------
% Uncomment to print the contents of the EEG structure:
%--------------------------------------------------------------------------
% EEG = eeg_checkset( EEG )

%--------------------------------------------------------------------------
% Uncomment to update the GUI:
%--------------------------------------------------------------------------
% eeglab redraw


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Dipole estimation and fitting - generate appropriate settings;
%$$$$$$
%$$$$$$ The transform parameters will vary depending on the model used
%$$$$$$ (BESA, BEM, etc.), and also on the cap montage (64 channels ~=
%$$$$$$ 128 channel).
%$$$$$$
%$$$$$$ To estimate dipoles, set the fitDipoles flag to true.
%$$$$$$
%$$$$$$ To specify the method as BESA, set the estimationType flag to 1,
%$$$$$$ and to specify BEM, set the estimationType clag to 2.
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
