%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Compute a time-frequency decomposition for every electrode
%$$$$$$ Store these in the EEG structure in the field EEG.TF
%$$$$$$
%$$$$$$ At themoment, I have this completely turned off - manual
%$$$$$$ computations below.
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
if isfield(cfg, 'calcTF') && ~isempty(cfg.calcTF)
    calcTF = cfg.calcTF;
    
else calcTF = 0;
    
end

%--------------------------------------------------------------------------
% Start conditional:
%--------------------------------------------------------------------------
if calcTF > 0
EEG.TF = [];
allersp = [];
allitc = [];
allpowbase = [];
alltimes = [];
allfreqs = [];
allerspboot = [];
allitcboot = [];

%--------------------------------------------------------------------------
% Start loop across electrodes:
%--------------------------------------------------------------------------
for elec = 1:EEG.nbchan
[ersp,itc,powbase,times,freqs,erspboot,itcboot] = pop_newtimef(EEG,...
1, elec,...
[EEG.xmin EEG.xmax]*1000,...
[3 0.5],...
'maxfreq', 40,...
'padratio', 16,...
'plotphase', 'off',...
'timesout', 200,...
'alpha', .05,...
'plotersp','off',...
'plotitc','off');

%--------------------------------------------------------------------------
% Create empty arrays if first electrode:
%--------------------------------------------------------------------------
if elec == 1  
    allersp = zeros([size(ersp) EEG.nbchan]);
    allitc = zeros([size(itc) EEG.nbchan]);
    allpowbase = zeros([size(powbase) EEG.nbchan]);
    alltimes = zeros([size(times) EEG.nbchan]);
    allfreqs = zeros([size(freqs) EEG.nbchan]);
    allerspboot = zeros([size(erspboot) EEG.nbchan]);
    allitcboot = zeros([size(itcboot) EEG.nbchan]);
   
end

allersp (:,:,elec) = ersp;
allitc (:,:,elec) = itc;
allpowbase (:,:,elec) = powbase;
alltimes (:,:,elec) = times;
allfreqs (:,:,elec) = freqs;
allerspboot (:,:,elec) = erspboot;
allitcboot (:,:,elec) = itcboot;

%--------------------------------------------------------------------------
% End loop across electrodes:
%--------------------------------------------------------------------------
end

EEG.TF.ersp = allersp;
EEG.TF.itc = allitc;
EEG.TF.powbase = allpowbase;
EEG.TF.times = alltimes;
EEG.TF.freqs = allfreqs;
EEG.TF.erspboot = allerspboot;
EEG.TF.itcboot = allitcboot;

%--------------------------------------------------------------------------
