%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Decompose into frequency bands and calculate power:
%$$$$$$
%$$$$$$ Set the following frequency bands:
%$$$$$$ delta = 1-4 Hz
%$$$$$$ theta = 4-8 Hz
%$$$$$$ alpha = 8-12 Hz
%$$$$$$ sigma = 12-15 Hz
%$$$$$$ mu = 10-12 Hz
%$$$$$$ full_beta = 13-30 Hz
%$$$$$$ low_beta = 13-18 Hz
%$$$$$$ high_beta = 18-30 Hz
%$$$$$$ gamma = 30-80 Hz ----- need to reset all of the filtering
%$$$$$$ parameters above, and use only a notch filter instead of a
%$$$$$$ highpass/lowpass combination
%$$$$$$
%$$$$$$ hpFilterCut and lpFilterCut were set well above
%$$$$$$
%$$$$$$ To retrieve power for an electrode, use the following example
%$$$$$$ syntax to extract the power from the 1st channel in the alpha band:
%$$$$$$ value = EEG.powerspec(1).alphaPower;
%$$$$$$
%$$$$$$ or, to get several channels:
%$$$$$$ values = [EEG.powerspec(1:10).alphaPower];
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%--------------------------------------------------------------------------
% Set flag to do/not do spectral analysis:
%--------------------------------------------------------------------------
if isfield(cfg, 'doSpec') && ~isempty(cfg.doSpec)
    doSpec = cfg.doSpec;
    
else doSpec = 0;
    
end

%--------------------------------------------------------------------------
% Evaluate flag:
%--------------------------------------------------------------------------
if doSpec > 0

%--------------------------------------------------------------------------
% Do the work:
%--------------------------------------------------------------------------
for numelec = 1:EEG.nbchan

%--------------------------------------------------------------------------
% Run spectopo for every electrode:
%--------------------------------------------------------------------------
[spectra,freqs] = spectopo(EEG.data(numelec,:,:), 0, EEG.srate,...
    'freqrange', [hpFilterCut lpFilterCut],...
    'plot', 'off');
 
%--------------------------------------------------------------------------
% Get the indices of the frequency bands of interest:
%--------------------------------------------------------------------------
deltaIdx        = find(freqs>1 & freqs<4);
thetaIdx        = find(freqs>4 & freqs<8);
alphaIdx        = find(freqs>8 & freqs<12);
muIdx           = find(freqs>10 & freqs<12);
sigmaIdx        = find(freqs>12 & freqs<15);
fullbetaIdx     = find(freqs>13 & freqs<30);
lowbetaIdx      = find(freqs>13 & freqs<18);
highbetaIdx     = find(freqs>18 & freqs<30);
smbetaIdx       = find(freqs>18 & freqs<22);
%gammaIdx = find(freqs>30 & freqs<80);

%--------------------------------------------------------------------------
% Compute absolute power:
%--------------------------------------------------------------------------
deltaPower      = mean(10.^(spectra(deltaIdx)/10));
thetaPower      = mean(10.^(spectra(thetaIdx)/10));
alphaPower      = mean(10.^(spectra(alphaIdx)/10));
muPower         = mean(10.^(spectra(muIdx)/10));
sigmaPower      = mean(10.^(spectra(sigmaIdx)/10));
fullbetaPower   = mean(10.^(spectra(fullbetaIdx)/10));
lowbetaPower    = mean(10.^(spectra(lowbetaIdx)/10));
highbetaPower   = mean(10.^(spectra(highbetaIdx)/10));
smbetaPower     = mean(10.^(spectra(smbetaIdx)/10));
%gammaPower      = mean(10.^(spectra(gammaIdx)/10));

%--------------------------------------------------------------------------
% Store signal power for each band and electrode:
%--------------------------------------------------------------------------
powerspec(numelec).deltaPower = deltaPower;
powerspec(numelec).thetaPower = thetaPower;
powerspec(numelec).alphaPower = alphaPower;
powerspec(numelec).muPower = muPower;
powerspec(numelec).sigmaPower = sigmaPower;
powerspec(numelec).fullbetaPower = fullbetaPower;
powerspec(numelec).lowbetaPower = lowbetaPower;
powerspec(numelec).highbetaPower = highbetaPower;
powerspec(numelec).smbetaPower = smbetaPower;

%--------------------------------------------------------------------------
% End loop for electrodes:
%--------------------------------------------------------------------------
end

%--------------------------------------------------------------------------
% Copy power back over to the EEG structure:
%--------------------------------------------------------------------------
EEG.powerspec = powerspec;

%--------------------------------------------------------------------------
% End conditional:
%--------------------------------------------------------------------------
end


